import { type FramePoseLandmarks } from '../landmark-extraction/landmark-data.interface';

/**
 * A time interval in seconds representing a continuous video segment.
 */
export interface SegmentInterval {
  startTime: number,
  endTime: number,
}

/**
 * Input data provided to an auto-segmentation algorithm model.
 */
export interface AutoSegmentationInput {
  landmarks: readonly FramePoseLandmarks[],
  framerate: number,
  duration: number,
  lambda?: number,
  minRegionLength?: number,
}

/**
 * Result data generated by an auto-segmentation algorithm model.
 */
export interface AutoSegmentationResult {
  activeRegions: [number, number][],
  segments: SegmentInterval[],
  shortTimeEnergy?: Float32Array | number[],
}

/**
 * Extensible contract for auto-segmentation models and heuristics.
 */
export interface AutoSegmentationModel {
  readonly id: string,
  readonly name: string,
  readonly description: string,

  /**
   * Evaluates pose landmarks and computes active video segments.
   *
   * @param input Kinematic landmark data, framerate, duration, and heuristic parameters.
   * @returns Computed segment boundaries and active intervals.
   */
  segment(input: AutoSegmentationInput): AutoSegmentationResult,
}
